{
  "title": "迷失祠堂",
  "scene": "你站在一座年久失修的祠堂前，阳光透过破碎的窗子洒在蜘蛛网上，屋内弥漫着一股陈旧的霉味。墙上挂着几幅祖先的画像，画像边缘泛黄，上面似乎有微弱的字迹，不仔细看很难发现。地上散落着一些破旧的祭器，有些许灰尘聚成的小山。你隐约听到屋内有轻微的响动。",
  "goal": "找到祠堂内藏着的家族秘密。",
  "clue": "祖先画像边缘的微弱字迹。",
  "choices": [
    {"id": "A", "text": "仔细检查画像边缘是否有字迹", "outcome": "你发现画像边缘有模糊的字迹，上面写着‘祠堂西角，石缝间有钥匙’。", "result": "success", "next": "next_level"},
    {"id": "B", "text": "清理地上的祭器，寻找可能的线索", "outcome": "祭器清理后，你发现一个较小的石块被压在下面，但并没有发现任何有用的线索。", "result": "partial", "next": "retry"},
    {"id": "C", "text": "四处摸索，寻找其他的入口", "outcome": "你并未发现其他入口，只摸到一些黏糊糊的东西，似乎很脏。", "result": "fail", "next": "retry"}
  ]
}
